export function subscriptionExpires(
    subscription?: SubscriptionModel | FreeSubscription | null,
    cancellationContext = false
): FreeSubscriptionResult | SubscriptionResult {
    if (!subscription || isFreeSubscription(subscription)) {
        return {
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        };
    }

    const activeTermOnly =
        cancellationContext ||
        subscription.Renew === Renew.Disabled ||
        subscription.UpcomingSubscription?.Renew === Renew.Disabled;
    const latestSubscription = activeTermOnly ? subscription : subscription.UpcomingSubscription ?? subscription;
    const renewDisabled = activeTermOnly || latestSubscription.Renew === Renew.Disabled;
    const renewEnabled = !renewDisabled && latestSubscription.Renew === Renew.Enabled;
    const subscriptionExpiresSoon = renewDisabled;

    const planName = latestSubscription.Plans?.[0]?.Title;

    if (subscriptionExpiresSoon) {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: latestSubscription.PeriodEnd,
        };
    } else {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: null,
        };
    }
}

